PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_epochs(epoch INTEGER PRIMARY KEY,parent_epoch INTEGER,root_hash TEXT NOT NULL,committed_at TEXT NOT NULL,writer_node TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_imports(import_id TEXT PRIMARY KEY,domain TEXT NOT NULL,source_ref TEXT NOT NULL,source_commit TEXT,evidence_class TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,content_hash TEXT,imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities(entity_id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semantic_records(record_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES entities(entity_id),predicate TEXT NOT NULL,object_text TEXT,object_ref TEXT REFERENCES entities(entity_id),epistemic_class TEXT NOT NULL,confidence REAL,epoch INTEGER NOT NULL,status TEXT NOT NULL,provenance_clay TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_semantic_lookup ON semantic_records(subject_id,predicate,status);
CREATE TABLE IF NOT EXISTS semantic_dependencies(dependency_id TEXT PRIMARY KEY,parent_ref TEXT NOT NULL,child_ref TEXT NOT NULL,relation TEXT NOT NULL,confidence REAL NOT NULL,evidence_class TEXT NOT NULL,provenance_clay TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_dep_parent ON semantic_dependencies(parent_ref,status);
CREATE INDEX IF NOT EXISTS idx_dep_child ON semantic_dependencies(child_ref,status);
CREATE TABLE IF NOT EXISTS organ_registry(organ_id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,functional_role TEXT NOT NULL,current_realization TEXT NOT NULL,lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('EXPLICIT','FUSED','EMERGENT_DISTRIBUTED','HISTORICAL_FAILURE_LINEAGE')),deletable INTEGER NOT NULL DEFAULT 0 CHECK(deletable=0),lineage_ref TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS rae_organ_delete_forbidden BEFORE DELETE ON organ_registry BEGIN SELECT RAISE(ABORT,'ORGAN_DELETE_FORBIDDEN'); END;
CREATE TABLE IF NOT EXISTS possibility_frames(frame_id TEXT PRIMARY KEY,cycle_id TEXT,realized_state_ref TEXT NOT NULL,constraints_clay TEXT NOT NULL,generative_map_ref TEXT NOT NULL,source_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hyperpositions(hyperposition_id TEXT PRIMARY KEY,frame_id TEXT NOT NULL REFERENCES possibility_frames(frame_id),subject_ref TEXT NOT NULL,context_clay TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('OPEN','PARTIALLY_RESOLVED','SELECTED','EXPIRED','REOPENED')),evidence_status TEXT NOT NULL,uncertainty REAL,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS hyperposition_alternatives(alternative_id TEXT PRIMARY KEY,hyperposition_id TEXT NOT NULL REFERENCES hyperpositions(hyperposition_id) ON DELETE CASCADE,lane TEXT NOT NULL CHECK(lane IN ('KNOWN','ANALOGOUS','COUNTERINTUITIVE','EMERGENT_NOVEL')),semantic_ref TEXT NOT NULL,proposition_clay TEXT NOT NULL,fit REAL NOT NULL,novelty REAL NOT NULL,evidence REAL NOT NULL,risk REAL NOT NULL,admissibility_state TEXT NOT NULL,provenance_clay TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gwt_episodes(episode_id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,candidate_set_hash TEXT NOT NULL,selected_alternative_id TEXT,competition_margin REAL,ignition REAL NOT NULL,addressable_receivers INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gwt_receiver_receipts(receipt_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL REFERENCES gwt_episodes(episode_id) ON DELETE CASCADE,receiver TEXT NOT NULL,addressable INTEGER NOT NULL,delivered INTEGER NOT NULL,reconstructed INTEGER NOT NULL,used INTEGER NOT NULL,local_effect INTEGER NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS receiver_stage_guard BEFORE INSERT ON gwt_receiver_receipts WHEN NEW.used=1 AND (NEW.delivered=0 OR NEW.reconstructed=0) BEGIN SELECT RAISE(ABORT,'GWT_USE_REQUIRES_DELIVERY_AND_RECONSTRUCTION'); END;
CREATE TRIGGER IF NOT EXISTS receiver_effect_guard BEFORE INSERT ON gwt_receiver_receipts WHEN NEW.local_effect=1 AND NEW.used=0 BEGIN SELECT RAISE(ABORT,'GWT_EFFECT_REQUIRES_USE'); END;
CREATE TABLE IF NOT EXISTS outcomes(outcome_id TEXT PRIMARY KEY,episode_id TEXT NOT NULL REFERENCES gwt_episodes(episode_id),observed_state_clay TEXT NOT NULL,verified INTEGER NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reentry_receipts(reentry_id TEXT PRIMARY KEY,outcome_id TEXT NOT NULL REFERENCES outcomes(outcome_id),from_episode_id TEXT NOT NULL,to_cycle_id TEXT NOT NULL,truth_class TEXT NOT NULL CHECK(truth_class IN ('TRUTHFUL_PROVENANCE','SHUFFLED','BROKEN_PROVENANCE','NONE')),delta_clay TEXT NOT NULL,applied INTEGER NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS emergence_gate_receipts(gate_id TEXT PRIMARY KEY,subject_ref TEXT NOT NULL,state_adequacy TEXT NOT NULL,receiver_use INTEGER NOT NULL,truthful_reentry INTEGER NOT NULL,lesion_effect REAL,rescue_recovery REAL,shuffle_delta REAL,ood_transfer REAL,macro_advantage REAL,cost_shadow REAL,verdict TEXT NOT NULL CHECK(verdict IN ('OPEN','ABSTAIN_STATE_INADEQUATE','REJECTED','SUPPORTED_FUNCTIONAL_PATTERN')),evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claycode_contract_receipts(receipt_id TEXT PRIMARY KEY,compiler_ref TEXT NOT NULL,grammar_ref TEXT NOT NULL,contract_version TEXT NOT NULL,software_status TEXT NOT NULL,physical_release_status TEXT NOT NULL,semantic_contract_clay TEXT NOT NULL,evidence_clay TEXT NOT NULL,created_at TEXT NOT NULL);
